    internal static class Defaults
    {
        internal static EqBand[][] JaggedEqBand8x10()
        {
            EqBand[][] result = new EqBand[8][];
            for (int i = 0; i < 8; ++i)
            {
                result[i] = new EqBand[10];
                for (int j = 0; j < 10; ++j)
                {
                    result[i][j] = new EqBand();
                }
            }
            return result;
        }
    }

